from collections import Counter

def task_func(student_grades, possible_grades=["A", "B", "C", "D", "F"]):
    # Map case-insensitive grade keys to their canonical display values,
    # while keeping whitespace significant.
    canonical_grades = []
    seen = set()
    for grade in possible_grades:
        if grade not in seen:
            canonical_grades.append(grade)
            seen.add(grade)

    normalized_to_canonical = {}
    for grade in canonical_grades:
        key = grade.casefold() if isinstance(grade, str) else grade
        if key not in normalized_to_canonical:
            normalized_to_canonical[key] = grade

    counts = Counter()
    for grade in student_grades:
        if isinstance(grade, str):
            key = grade.casefold()
            if key in normalized_to_canonical:
                counts[normalized_to_canonical[key]] += 1

    data = pd.DataFrame(
        {
            "Grade": canonical_grades,
            "Count": [counts.get(grade, 0) for grade in canonical_grades],
        }
    ).set_index("Grade")
    data.index.name = "Grade"

    fig, ax = plt.subplots()
    ax.bar(data.index.astype(str), data["Count"])
    ax.set_title("Grade Distribution")
    ax.set_xlabel("Grade")
