def task_func(array, seed=None):
    arr = np.asarray(array)

    if arr.ndim != 2:
        raise ValueError("Input array must be 2D.")

    n_samples, n_features = arr.shape

    if n_samples == 0 or n_features == 0:
        return pd.DataFrame(columns=["PC1", "PC2"])

    rng = np.random.default_rng(seed)
    shuffled_indices = rng.permutation(n_features) if n_features > 1 else np.arange(n_features)
    arr_shuffled = arr[:, shuffled_indices]

    n_components = min(2, n_features, n_samples)

    pca = PCA(n_components=n_components)
    transformed = pca.fit_transform(arr_shuffled)

    if n_components == 1:
        return pd.DataFrame(transformed, columns=["PC1"])

    return pd.DataFrame(transformed, columns=["PC1", "PC2"])
